document.addEventListener("DOMContentLoaded",function(){const images=document.querySelectorAll("img[data-src]");if("IntersectionObserver"in window){const imageObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;const dataSrc=img.dataset.src;img.classList.add("loading");const tempImg=new Image;tempImg.onload=function(){img.src=dataSrc;img.removeAttribute("data-src");img.classList.remove("loading");img.classList.add("loaded");observer.unobserve(img)};tempImg.onerror=function(){img.classList.remove("loading");img.classList.add("error");img.src="data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22400%22 height=%22300%22%3E%3Crect fill=%22%23f0f0f0%22 width=%22400%22 height=%22300%22/%3E%3Ctext x=%2250%25%22 y=%2250%25%22 text-anchor=%22middle%22 dy=%22.3em%22 fill=%22%23999%22 font-size=%2216%22%3EImage not available%3C/text%3E%3C/svg%3E";observer.unobserve(img)};tempImg.src=dataSrc}})},{rootMargin:"50px"});images.forEach(img=>imageObserver.observe(img))}else{images.forEach(img=>{const tempImg=new Image;tempImg.onload=function(){img.src=img.dataset.src;img.removeAttribute("data-src");img.classList.add("loaded")};tempImg.onerror=function(){img.classList.add("error")};tempImg.src=img.dataset.src})}});